 <Drawer open={!!detail} width="min(1500px, 100vw)" onClose={closeCase} title={<Space>{detail?.title}{detail&&status(detail.status)}</Space>} extra={detail&&<Tag>版本 {detail.version}</Tag>}>{detail&&<><Space wrap className="section-bottom"><Button onClick={()=>navigate(()=>navigation.update({view:'knowledge',caseId:detail.id}))}>录入专家经验与条件</Button>{(detail.diagnosis.experience_references??[]).map((r:RowData)=><Button type="link" key={r.record_id} onClick={()=>showExperienceReference(r)} style={{whiteSpace:'normal',height:'auto',textAlign:'left'}}>经验依据：{r.title} · v{r.revision}（候选）</Button>)}</Space><div className="case-workspace"><div className="case-main">{detail.review_flags?.some((f:RowData)=>!f.resolved)&&<Alert className="section-bottom" type="warning" showIcon message="已引用的检测事实出现更正，需重新核对" description={<List size="small" dataSource={detail.review_flags.filter((f:RowData)=>!f.resolved)} renderItem={(f:RowData)=><List.Item><a href={'/api/evidence-records/inspection/'+f.correction_id} target="_blank" rel="noreferrer">查看更正 {f.correction_id.slice(0,8)}</a>；通过关键补证核对，已结案先受控重开。历史事实和放行决定保留。</List.Item>}/>}/>}<Space wrap className="section-bottom case-actions">{can('diagnose')&&['accepted','needs_evidence','diagnosed','retest_failed','rejected','execution_failed','partially_executed'].includes(detail.status)&&<Button type="primary" loading={busy} onClick={()=>perform(()=>api(`/cases/${detail.id}/diagnose`,{version:detail.version}),'诊断已记录').catch(()=>{})}>启动证据诊断</Button>}{can('plan')&&['diagnosed','needs_evidence','awaiting_approval','rejected','approved','retest_failed','partially_executed','execution_failed'].includes(detail.status)&&<Button onClick={()=>open('plan',{action_type:'inspect',sample_unit:'bottle',expires_in_hours:24,stabilization_minutes:0,observation_minutes:0})}>提交整改与复测方案</Button>}{can('close')&&detail.status==='retest_passed'&&<Button type="primary" onClick={()=>open('close',{root_cause_confirmation:'unverified',quality_disposition:'await_release'})}>结案归档</Button>}{can('release')&&detail.status==='closed'&&!detail.outcome?.released&&<Button onClick={()=>{setReleaseReason('');dialogs.confirm({title:'独立确认正式质量放行',content:<Input.TextArea aria-label="质量放行依据" placeholder="核对本厂有效质量规范，填写独立放行理由" onChange={e=>setReleaseReason(e.target.value)}/>,onOk:()=>{const reason=releaseReasonRef.current.trim();if(reason.length<3)throw new Error('请填写至少3字的独立放行理由');return perform(()=>api(`/cases/${detail.id}/release`,{version:detail.version,reason}));}});}}>质量放行</Button>}{can('case')&&!['closed','cancelled'].includes(detail.status)&&<Button onClick={()=>open('evidence')}>补充证据</Button>}{can('plan')&&!['closed','cancelled','awaiting_retest','inconclusive','retest_passed'].includes(detail.status)&&<Button onClick={()=>open('plan',{action_type:'inspect',sample_unit:'sample',expires_in_hours:24,stabilization_minutes:0,observation_minutes:0,save_as_draft:true})}>生成方案草稿</Button>}{can('close')&&['closed','cancelled'].includes(detail.status)&&<Button onClick={()=>open('reopen')}>申请重新调查</Button>}{can('file')&&uploadButton}</Space><Descriptions bordered size="small" column={2} items={[{key:'p',label:'工艺',children:processName[detail.process]},{key:'s',label:'来源',children:provenance(detail.context.provenance)},{key:'d',label:'目标缺陷',children:detail.context.defect},{key:'r',label:'调查轮次',children:detail.rounds},{key:'a',label:'对象关联',children:detail.context.association==="needs_check"?"待核对":"已核实"},{key:'m',label:'模型增强',children:({disabled:'未启用',unavailable:'暂不可用',validated:'已校验'} as RowData)[detail.diagnosis.model_status]??'尚未分析'}]}/><Tabs className="section" items={[{key:'diagnosis',label:'五维诊断与补证',children:<><Alert type="info" showIcon message="候选原因使用相对评分，不是因果概率。整改效果、根因确认及质量处置分别记录。"/>{detail.diagnosis.features&&<Card className="section" title="历史证据特征"><p>{detail.diagnosis.features.limitations}</p><p>24小时授权观察：{detail.diagnosis.features.inspection_count} 条；时间聚集段：{detail.diagnosis.features.time_clusters.length}；{detail.diagnosis.features.truncated?'已达500条分析上限，请缩小范围':'未截断'}</p><DataTable<RowData> tableId="main-15" size="small" rowKey={r=>r.equipment_id+r.metric+r.unit+r.value_type} dataSource={detail.diagnosis.features.parameters} columns={[{title:'设备/指标',render:(_,r)=>r.equipment_id+' / '+r.metric},{title:'值类型',dataIndex:'value_type',render:v=>v==='setpoint'?'设定值':'实测值'},{title:'历史范围',render:(_,r)=>r.minimum===null?'无有效采样':r.minimum+'～'+r.maximum+' '+r.unit},{title:'有效样本',dataIndex:'good_samples'},{title:'SOP比对',dataIndex:'status'}]}/><details><summary>时间聚集与批次/工位分组依据</summary><pre>{JSON.stringify({time_clusters:detail.diagnosis.features.time_clusters,groups:detail.diagnosis.features.group_concentration},null,2)}</pre></details></Card>}<List dataSource={detail.diagnosis.missing_evidence??[]} renderItem={(item:any)=><List.Item><Tag color="orange">待补证</Tag>{item}</List.Item>}/><AssistantTools key={detail.id+':'+detail.version} detail={detail} canPlan={can('plan')} onDraft={draft=>open('plan',{save_as_draft:true,source_run_id:draft.model?.draft_available?draft.model.run_id:'',sample_unit:'bottle',expires_in_hours:24,actions:draft.actions.map((a:RowData)=>({...a,action_id:crypto.randomUUID(),parameter_rows:Object.entries(a.parameters??{}).map(([metric,value])=>({metric,value}))}))})}/><EvidenceTasks detail={detail} files={files} canEdit={can('case')} onComplete={()=>api('/cases/'+detail.id).then(setDetail)}/>{(detail.diagnosis.candidates??[]).length===0?<Empty description="尚无适用且获审核的根因依据，可补充证据或由工程师制定人工核验方案"/>:(detail.diagnosis.candidates??[]).map((c:RowData,i:number)=><Card key={i} title={<Space><Tag>{dimensions[c.dimension]}</Tag>{c.cause}</Space>} className="section-bottom"><p><Tag color={c.condition_evaluations?'blue':'purple'}>{c.condition_evaluations?'规则证据结果':'AI 辅助草稿'}</Tag>{c.ranking_basis} · 相对评分 {c.relative_score}</p><p>支撑证据：{c.support_refs.join('、')||'暂无'}</p><p>反证：{c.counter_refs.join('、')||'尚未提供'}</p><p>状态：{{unverified:'尚未验证',evidence_supported:'证据支持',excluded:'已排除',human_confirmed:'人工确认'}[c.status as string]??c.status}</p><p>缺失或无效证据：{c.missing_evidence?.join('；')||'无已知缺项'}</p><p>下一步：{c.next_checks.join('；')}</p>{c.condition_evaluations?.length>0&&<DataTable<RowData> tableId="main-16" size="small" rowKey={r=>r.role+r.metric+JSON.stringify(r.condition)} pagination={false} dataSource={c.condition_evaluations} columns={[{title:'用途',dataIndex:'role',render:v=>v==='counter'?'反证':'支撑条件'},{title:'指标',dataIndex:'metric'},{title:'实测/设定',render:(_,r)=>r.condition.value_type==='measured'?'实测':'设定'},{title:'结果',dataIndex:'state'},{title:'值',render:(_,r)=>r.value===undefined?'—':r.value+' '+r.unit}]}/>}</Card>)}</>},{key:'plans',label:'方案与审批',children:<List dataSource={detail.plans} renderItem={(p:any)=><List.Item><Card style={{width:'100%'}} title={<Space>方案 v{p.revision}{status(p.status)}</Space>} extra={<Space>{p.status==='draft'&&can('plan')&&<Button onClick={()=>perform(()=>api(`/cases/${detail.id}/plans/${p.id}/submit`,{version:detail.version})).catch(()=>{})}>提交审批</Button>}{p.status==='awaiting_approval'&&can('approve')&&<Button onClick={()=>{setSelected(p);open('approve',{approved:true});}}>审批／驳回</Button>}{p.status==='approved'&&can('execute')&&<Button onClick={()=>{setSelected(p);open('execute',{success:true,action_results:p.content.actions.map((a:RowData)=>({action_id:a.action_id,status:'not_started',notes:'',evidence_ids:[]}))});}}>登记执行</Button>}{p.status==='executed'&&can('retest')&&['awaiting_retest','inconclusive'].includes(detail.status)&&<Button onClick={()=>{setSelected(p);open('retest',{sample_unit:p.content.retest.sample_unit,conditions_met:false,other_constraints_met:false});}}>登记复测</Button>}</Space>}><List dataSource={p.content.actions} renderItem={(a:any)=><List.Item>{a.description}</List.Item>}/><p>复测：{p.content.retest.method}；至少 {p.content.retest.min_samples} {units[p.content.retest.sample_unit]??p.content.retest.sample_unit}；不良率 ≤ {p.content.retest.max_defect_rate}</p><p>有效期至 {time(p.expires_at)}</p></Card></List.Item>}/>},{key:'evidence',label:'证据与记录',children:<><p>{detail.context.notes||'未提供人工说明'}</p><List dataSource={detail.context.evidence_ids??[]} renderItem={(id:any)=><List.Item><a href={'/api/files/'+id} target="_blank" rel="noreferrer">查看授权证据 {id}</a></List.Item>}/><h4>执行回执</h4><List dataSource={detail.receipts} renderItem={(r:any)=><List.Item><div>{time(r.effective_at)} · {r.content.actual_actions} · 偏差：{r.content.deviations||'无'}<ActionReceiptDetails content={r.content} actions={detail.plans.find((p:RowData)=>p.id===r.plan_id)?.content.actions??[]}/></div></List.Item>}/><h4>复测结果</h4><List dataSource={detail.retests} renderItem={(r:any)=><List.Item>{({passed:'达标',failed:'未达标',inconclusive:'无法判断'} as RowData)[r.verdict]??r.verdict} · 样本 {r.result.sample_count} · 不良件 {r.result.defective_count}</List.Item>}/></>},{key:'timeline',label:'案件时间线',children:<Timeline items={(detail.timeline??[]).map((a:RowData)=>({children:<><b>{a.action}</b><br/><span className="muted">{time(a.created_at)} · {a.actor_id}</span></>}))}/>} ]}/></div><aside className="case-evidence-sidebar" aria-label="案件证据侧栏"><h3>原始事实与版本</h3><Tag>案件 v{detail.version}</Tag><p>产线：{data.masters?.find((m:RowData)=>m.id===detail.line_id)?.name??detail.line_id}</p><p>证据快照 v{detail.context.snapshot_version}</p><p>工艺：{detail.context.route_snapshot?.name??'尚无已绑定版本依据'}</p><p>配方：{detail.context.recipe_snapshot?.name??'未引用正式配方'}</p><p>关联：{detail.context.association==='needs_check'?'待人工核对':'已记录关联依据'}</p><h3>授权原文件</h3>{[...new Set<string>([...(detail.context.evidence_ids??[]),...(detail.context.inspection_snapshots??[]).flatMap((r:RowData)=>r.result?.image_ids??[])])].map(id=><a key={id} href={'/api/files/'+id} target="_blank" rel="noreferrer">{files.find(f=>f.id===id)?.filename??id}</a>)}<h3>人工决定</h3><p>整改效果：{({passed:'复测达标',failed:'复测未达标',inconclusive:'无法判断'} as RowData)[detail.outcome.rectification_effect]??detail.outcome.rectification_effect??'待复测'}</p><p>根因确认：{({unverified:'尚未确认',evidence_supported:'证据支持',human_confirmed:'专家人工确认'} as RowData)[detail.outcome.root_cause_confirmation]??detail.outcome.root_cause_confirmation??'尚未确认'}</p><p>正式放行：{detail.outcome.released?'已由授权人员独立登记':'尚未放行'}</p></aside></div></>}</Drawer>
